#include <algorithm>
#include <cctype>
#include <cstdint>
#include <map>
#include <memory>
#include <sstream>
#include <string>
#include <vector>

constexpr long ERROR_SUCCESS = 0, ERROR_FILE_NOT_FOUND = 2, ERROR_UNSUPPORTED_TYPE = 1630;
enum class Type { String, Dword, MultiString };

std::string encodeMulti(const std::vector<std::string>& values)
{
    std::string out;
    for (const std::string& v : values) if (!v.empty()) { out += v; out += '\0'; }
    if (out.empty()) out += '\0';
    out += '\0';
    return out;
}

std::vector<std::string> decodeMulti(const std::string& data)
{
    std::vector<std::string> out;
    std::size_t pos{ 0 };
    while (pos < data.size())
    {
        const std::size_t end{ data.find('\0', pos) };
        const std::string s{ data.substr(pos, end == std::string::npos ? std::string::npos : end - pos) };
        if (s.empty()) break;
        out.push_back(s);
        if (end == std::string::npos) break;
        pos = end + 1;
    }
    return out;
}

namespace
{
    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }

    std::vector<std::string> split(const std::string& key)
    {
        std::vector<std::string> parts;
        std::stringstream in{ key };
        for (std::string p; std::getline(in, p, '\\');) if (!p.empty()) parts.push_back(p);
        return parts;
    }
}

class Registry
{
public:
    long setString(const std::string& key, const std::string& name, const std::string& value) { return set(key, name, { Type::String, value, 0 }); }
    long setDword(const std::string& key, const std::string& name, std::uint32_t value) { return set(key, name, { Type::Dword, "", value }); }
    long setMulti(const std::string& key, const std::string& name, const std::vector<std::string>& values) { return set(key, name, { Type::MultiString, encodeMulti(values), 0 }); }

    long getString(const std::string& key, const std::string& name, std::string& out) const
    {
        const Value* v{ nullptr };
        if (const long st{ find(key, name, Type::String, v) }; st != ERROR_SUCCESS) return st;
        out = v->text;
        return ERROR_SUCCESS;
    }

    long getDword(const std::string& key, const std::string& name, std::uint32_t& out) const
    {
        const Value* v{ nullptr };
        if (const long st{ find(key, name, Type::Dword, v) }; st != ERROR_SUCCESS) return st;
        out = v->number;
        return ERROR_SUCCESS;
    }

    long getMulti(const std::string& key, const std::string& name, std::vector<std::string>& out) const
    {
        const Value* v{ nullptr };
        if (const long st{ find(key, name, Type::MultiString, v) }; st != ERROR_SUCCESS) return st;
        out = decodeMulti(v->text);
        return ERROR_SUCCESS;
    }

    long deleteValue(const std::string& key, const std::string& name)
    {
        Key* k{ walk(key, false) };
        if (!k || !k->values.erase(lower(name))) return ERROR_FILE_NOT_FOUND;
        return ERROR_SUCCESS;
    }

    long deleteTree(const std::string& key)
    {
        const auto parts{ split(key) };
        if (parts.empty()) return ERROR_FILE_NOT_FOUND;
        Key* parent{ &m_root };
        for (std::size_t i{ 0 }; i + 1 < parts.size(); ++i)
        {
            auto it{ parent->children.find(lower(parts[i])) };
            if (it == parent->children.end()) return ERROR_FILE_NOT_FOUND;
            parent = it->second.get();
        }
        return parent->children.erase(lower(parts.back())) ? ERROR_SUCCESS : ERROR_FILE_NOT_FOUND;
    }

    std::vector<std::string> subkeys(const std::string& key) const
    {
        std::vector<std::string> out;
        if (const Key* k{ const_cast<Registry*>(this)->walk(key, false) })
            for (const auto& [lowered, child] : k->children) out.push_back(child->name);   // map order is case-insensitive order
        return out;
    }

private:
    struct Value { Type type; std::string text; std::uint32_t number; std::string name; };
    struct Key
    {
        std::string name;
        std::map<std::string, std::unique_ptr<Key>> children;   // by lower-case name
        std::map<std::string, Value> values;                    // by lower-case name
    };

    Key* walk(const std::string& key, bool create)
    {
        Key* k{ &m_root };
        for (const std::string& part : split(key))
        {
            auto it{ k->children.find(lower(part)) };
            if (it == k->children.end())
            {
                if (!create) return nullptr;
                auto child{ std::make_unique<Key>() };
                child->name = part;
                it = k->children.emplace(lower(part), std::move(child)).first;
            }
            k = it->second.get();
        }
        return k;
    }

    long set(const std::string& key, const std::string& name, Value v)
    {
        Key* k{ walk(key, true) };
        auto it{ k->values.find(lower(name)) };
        v.name = it == k->values.end() ? name : it->second.name;
        k->values[lower(name)] = v;
        return ERROR_SUCCESS;
    }

    long find(const std::string& key, const std::string& name, Type type, const Value*& out) const
    {
        const Key* k{ const_cast<Registry*>(this)->walk(key, false) };
        if (!k) return ERROR_FILE_NOT_FOUND;
        auto it{ k->values.find(lower(name)) };
        if (it == k->values.end()) return ERROR_FILE_NOT_FOUND;
        if (it->second.type != type) return ERROR_UNSUPPORTED_TYPE;
        out = &it->second;
        return ERROR_SUCCESS;
    }

    Key m_root;
};

unitTests:
using Strings = std::vector<std::string>;
TEST("multi-strings") {
    CHECK_EQ(encodeMulti({ "a", "bc" }), std::string("a\0bc\0\0", 6)); CHECK_EQ(encodeMulti({}), std::string(2, '\0')); CHECK_EQ(encodeMulti({ "x", "", "y" }), std::string("x\0y\0\0", 5));
    CHECK_EQ(decodeMulti(std::string("a\0bc\0\0", 6)), (Strings{ "a", "bc" })); CHECK(decodeMulti(std::string(2, '\0')).empty()); CHECK_EQ(decodeMulti(std::string("a\0\0b\0\0", 6)), (Strings{ "a" }));
}
TEST("values and types") {
    Registry r; CHECK_EQ(r.setDword("Software\\Xenon\\Notes", "WordWrap", 1), ERROR_SUCCESS); CHECK_EQ(r.setString("software\\XENON\\notes", "Font", "Cascadia Mono"), ERROR_SUCCESS);
    std::uint32_t d = 0; CHECK_EQ(r.getDword("SOFTWARE\\xenon\\Notes", "wordwrap", d), ERROR_SUCCESS); CHECK_EQ(d, 1u);
    std::string s = "unchanged"; CHECK_EQ(r.getString("Software\\Xenon\\Notes", "WordWrap", s), ERROR_UNSUPPORTED_TYPE); CHECK_EQ(s, std::string("unchanged"));
    CHECK_EQ(r.getString("Software\\Xenon\\Notes", "Missing", s), ERROR_FILE_NOT_FOUND); CHECK_EQ(r.getString("Software\\Nobody", "Font", s), ERROR_FILE_NOT_FOUND);
    r.setString("Software\\Xenon\\Notes", "WORDWRAP", "yes"); CHECK_EQ(r.getString("Software\\Xenon\\Notes", "WordWrap", s), ERROR_SUCCESS); CHECK_EQ(s, std::string("yes"));
}
TEST("lists") { Registry r; r.setMulti("Software\\Xenon", "Recent", { "C:\\a.txt", "C:\\b.txt" }); Strings v; CHECK_EQ(r.getMulti("Software\\Xenon", "recent", v), ERROR_SUCCESS); CHECK_EQ(v, (Strings{ "C:\\a.txt", "C:\\b.txt" })); }
TEST("subkeys and deleting") {
    Registry r; r.setDword("Software\\Xenon\\Notes", "A", 1); r.setDword("Software\\xenon\\Finder", "B", 2); r.setDword("Software\\Zebra", "C", 3); r.setDword("Software\\apple", "D", 4);
    CHECK_EQ(r.subkeys("Software"), (Strings{ "apple", "Xenon", "Zebra" })); CHECK_EQ(r.subkeys("software\\XENON"), (Strings{ "Finder", "Notes" }));
    CHECK_EQ(r.deleteValue("Software\\Zebra", "c"), ERROR_SUCCESS); CHECK_EQ(r.deleteValue("Software\\Zebra", "c"), ERROR_FILE_NOT_FOUND);
    CHECK_EQ(r.deleteTree("Software\\Xenon"), ERROR_SUCCESS); CHECK_EQ(r.subkeys("Software"), (Strings{ "apple", "Zebra" }));
    std::uint32_t d = 0; CHECK_EQ(r.getDword("Software\\Xenon\\Notes", "A", d), ERROR_FILE_NOT_FOUND); CHECK_EQ(r.deleteTree("Software\\Xenon"), ERROR_FILE_NOT_FOUND); CHECK(r.subkeys("Nowhere").empty());
}

